mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, inner.* FROM ( SELECT BD.BRD_NO, BD.BRD_TITL_NM, BD.BRD_CONT, BD.BRD_PBLS_DTM, BD.BRD_VW_CNT, BD.BRD_MOD_DTM, BD.BRD_DEL_YN, BDC.BRD_CODE AS BDC_BRD_CODE, BDC.BRD_CTGRY AS BDC_BRD_CTGRY, BDC.BRD_CMNT_YN AS BDC_BRD_CMNT_YN, MEM.MBR_CD,
-- 공지 정보 N.NOTICE_TYPE AS N_NOTICE_TYPE, C.CODE_NAME AS N_NOTICE_TYPE_NAME
FROM BOARD BD LEFT JOIN MEMBER MEM ON BD.MBR_CD = MEM.MBR_CD LEFT JOIN BOARD_CARTEGORY BDC ON BD.BRD_CODE = BDC.BRD_CODE LEFT JOIN NOTICE N ON N.NOTICE_NO = BD.BRD_NO LEFT JOIN COMMON_CODE C ON C.CODE_GROUP = N.NOTICE_TYPE_GRP_CD AND C.CODE_VALUE = N.NOTICE_TYPE WHERE BD.BRD_DEL_YN = 'N' ORDER BY BD.BRD_PBLS_DTM DESC ) inner WHERE ROWNUM <= #{lastRecordIndex} ) WHERE rn >= #{firstRecordIndex}
